<script>
(function(){const form=document.getElementById('platform-notification-form'),source=document.getElementById('notification-message-source'),hidden=document.getElementById('notification-message-html'),tenants=document.getElementById('notification-tenants'),result=document.getElementById('notification-preview-result'),toolbar=document.getElementById('notification-editor-toolbar');let quill=null;if(window.createVoxelQuillEditor){quill=window.createVoxelQuillEditor(source,{toolbar:'#notification-editor-toolbar',placeholder:'<?= htmlspecialchars(t('platform_notifications.message'), ENT_QUOTES) ?>'})}else{toolbar.classList.add('d-none');source.contentEditable='true';source.classList.add('border','rounded','p-2')}function sync(){hidden.value=quill?quill.root.innerHTML:source.innerHTML;const scoped=form.querySelector('input[name="escopo"]:checked')?.value==='tenant';tenants.classList.toggle('d-none',!scoped);tenants.querySelectorAll('input').forEach(e=>e.required=scoped)}sync();form.querySelectorAll('input[name="escopo"]').forEach(e=>e.addEventListener('change',sync));form.addEventListener('submit',sync);document.getElementById('notification-preview').addEventListener('click',async()=>{sync();result.textContent='…';const response=await fetch(form.dataset.previewUrl,{method:'POST',headers:{'X-Requested-With':'XMLHttpRequest'},body:new FormData(form)});const data=await response.json();result.textContent=data.ok?data.total+' <?= htmlspecialchars(t('platform_notifications.estimated_recipients'), ENT_QUOTES) ?>':(data.message||'<?= htmlspecialchars(t('platform_notifications.preview_error'), ENT_QUOTES) ?>')})})();
</script>
